-- =============================================================
-- Edge cases for schema and object browsing.
-- Run with: db2 -tvf edge_cases.sql
-- =============================================================

-- A schema with nothing in it: it must still be listed.
CREATE SCHEMA EMPTY_SCHEMA;

-- A schema, a table and columns whose names only exist as delimited
-- identifiers: mixed case, spaces, a reserved word, punctuation, a quote
-- and a non-ASCII letter.
CREATE SCHEMA "Mixed Case";

CREATE TABLE "Mixed Case"."Order Details" (
    "Order Id" INTEGER NOT NULL,
    "Unit Price" DECIMAL(9, 2) NOT NULL DEFAULT 0,
    "select" VARCHAR(20),
    "Qty#" SMALLINT,
    "O'Brien" VARCHAR(30),
    "Größe" VARCHAR(10),
    PRIMARY KEY ("Order Id")
);

COMMENT ON TABLE "Mixed Case"."Order Details" IS 'Line items (delimited names)';

INSERT INTO "Mixed Case"."Order Details" ("Order Id", "Unit Price", "select", "Qty#", "O'Brien", "Größe")
    VALUES (1, 9.99, 'first', 3, 'it''s', 'groß');

CREATE VIEW "Mixed Case"."Cheap Orders" AS
    SELECT "Order Id", "Unit Price" FROM "Mixed Case"."Order Details" WHERE "Unit Price" < 10;

-- ---------------------------------------------------------
-- One column per type family, with the modifiers the catalog
-- reports in different ways (length, precision/scale, FOR BIT
-- DATA, LOB sizes, fractional seconds), plus an identity, a
-- generated column, defaults and an implicitly hidden column.
-- ---------------------------------------------------------

CREATE TABLE TEST_SCHEMA.TYPE_METADATA_TEST (
    ID BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    COL_CHAR CHAR(10) NOT NULL DEFAULT 'N/A',
    COL_VARCHAR VARCHAR(255),
    COL_BIT_DATA VARCHAR(16) FOR BIT DATA,
    COL_GRAPHIC GRAPHIC(4),
    COL_VARGRAPHIC VARGRAPHIC(40),
    COL_SMALLINT SMALLINT DEFAULT 1,
    COL_INTEGER INTEGER,
    COL_DECIMAL DECIMAL(18, 4) DEFAULT 0,
    COL_DECFLOAT16 DECFLOAT(16),
    COL_DECFLOAT34 DECFLOAT(34),
    COL_REAL REAL,
    COL_DOUBLE DOUBLE,
    COL_BOOLEAN BOOLEAN DEFAULT FALSE,
    COL_DATE DATE DEFAULT CURRENT DATE,
    COL_TIME TIME,
    COL_TIMESTAMP TIMESTAMP DEFAULT CURRENT TIMESTAMP,
    COL_TIMESTAMP12 TIMESTAMP(12),
    COL_CLOB CLOB(1M),
    COL_DBCLOB DBCLOB(64K),
    COL_BLOB BLOB(2M),
    COL_BINARY BINARY(16),
    COL_VARBINARY VARBINARY(64),
    COL_XML XML,
    COL_COMPUTED INTEGER GENERATED ALWAYS AS (LENGTH(COL_VARCHAR)),
    COL_HIDDEN TIMESTAMP NOT NULL IMPLICITLY HIDDEN
        GENERATED ALWAYS FOR EACH ROW ON UPDATE AS ROW CHANGE TIMESTAMP,
    PRIMARY KEY (ID)
);

COMMENT ON COLUMN TEST_SCHEMA.TYPE_METADATA_TEST.COL_DECIMAL IS 'Amount, 4 decimals';

-- One row with a value in every column, for the result-set type tests.
INSERT INTO TEST_SCHEMA.TYPE_METADATA_TEST (
    COL_CHAR, COL_VARCHAR, COL_BIT_DATA, COL_GRAPHIC, COL_VARGRAPHIC, COL_SMALLINT, COL_INTEGER,
    COL_DECIMAL, COL_DECFLOAT16, COL_DECFLOAT34, COL_REAL, COL_DOUBLE, COL_BOOLEAN, COL_DATE,
    COL_TIME, COL_TIMESTAMP, COL_TIMESTAMP12, COL_CLOB, COL_DBCLOB, COL_BLOB, COL_BINARY,
    COL_VARBINARY, COL_XML
) VALUES (
    'abc', 'héllo wörld 所有', X'CAFEBABE', 'グラ', '变长', 7, -42,
    1234.5678, 1.5, 12345678901234567890.123456789, 1.25, 75000.5, TRUE, '2024-02-29',
    '13:45:10', '2024-02-29-13.45.10.123456', '2024-02-29-13.45.10.123456789012', 'clob text',
    'dbclob 文本', BLOB(X'89504E470D0A1A0A0000'), BX'00112233445566778899AABBCCDDEEFF',
    BX'DEADBEEF', '<a><b>1</b></a>'
);

-- A row of NULLs (only the identity and the NOT NULL default are set).
INSERT INTO TEST_SCHEMA.TYPE_METADATA_TEST (COL_VARCHAR) VALUES (NULL);

-- ---------------------------------------------------------
-- Enough rows to need several grid pages (Tabularis loads 500
-- rows per page by default).
-- ---------------------------------------------------------

CREATE TABLE TEST_SCHEMA.PAGING_TEST (
    N INTEGER NOT NULL,
    LABEL VARCHAR(20),
    PRIMARY KEY (N)
);

INSERT INTO TEST_SCHEMA.PAGING_TEST (N, LABEL)
    WITH SEQ (N) AS (VALUES 1 UNION ALL SELECT N + 1 FROM SEQ WHERE N < 1200)
    SELECT N, 'row ' || N FROM SEQ;

-- ---------------------------------------------------------
-- A table without a primary key or unique index, holding two
-- identical rows, NULLs and a LOB: rows can only be told apart
-- by the values of all their columns.
-- ---------------------------------------------------------

CREATE TABLE TEST_SCHEMA.KEYLESS_TEST (
    CODE VARCHAR(10),
    QTY INTEGER,
    NOTE CLOB(1K),
    CREATED DATE
);

INSERT INTO TEST_SCHEMA.KEYLESS_TEST (CODE, QTY, NOTE, CREATED) VALUES ('A', 1, 'first', '2024-01-01');
INSERT INTO TEST_SCHEMA.KEYLESS_TEST (CODE, QTY, NOTE, CREATED) VALUES ('A', 1, 'first', '2024-01-01');
INSERT INTO TEST_SCHEMA.KEYLESS_TEST (CODE, QTY, NOTE, CREATED) VALUES ('B', NULL, NULL, NULL);
INSERT INTO TEST_SCHEMA.KEYLESS_TEST (CODE, QTY, NOTE, CREATED) VALUES ('C', 3, 'third', '2024-03-03');
